// Streams (§5.4 "Streams"), a clause of the host API row: a folder plugin's host half (fixtures/acceptance-stream-a) streams
// a few megabytes of generated bytes to its own page (its sidebar button's component, mounted in a frame of its own layer in
// the run's app as soon as it runs), and the page reports the count and a checksum; the page streams generated bytes back to
// its host half, which reports its own; and a second folder plugin's point handler (acceptance-stream-b, in a host process of
// its own) answers the first's `points.stream` call with a stream, which the first reads, counting and checksumming. The
// run holds each count and checksum to the one it computes itself from the same generator. A stream to a half the plugin
// has not, and a write to a stream that isn't its own, are refused; the daemon's log has a line for each stream opened and
// ended, with its bytes.
import { cpSync } from "node:fs";
import { join } from "node:path";

export const STREAMS_CLAUSE = "streams: a host half streams megabytes to its own page and the page streams back, each end's count and checksum equal to the run's; a second plugin's point handler answers a caller with a stream, count and checksum equal; a stream to a half the plugin hasn't is refused";

/** What the clause needs of the run. */
export interface StreamsClauseDeps {
  request<T>(method: string, params: unknown, timeoutMs?: number): Promise<T>;
  /** Installs a folder the user's way and presses its OK card; resolves once it runs. */
  install(folder: string, id: string): Promise<void>;
  /** Where fixtures are copied to. */
  srcDir: string;
  /** The daemon's log so far. */
  daemonLog(): string;
  fail(why: string): never;
}

const A = "acceptance-stream-a";
const B = "acceptance-stream-b";

export interface Counted {
  count: number;
  sum: number;
}

/** Bytes `from`..`from + n` of the stream of `seed`: the generator every half of the fixtures carries. */
export function gen(seed: number, from: number, n: number): Uint8Array {
  const b = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const k = from + i;
    b[i] = (k * 131 + (k >>> 8) * 7 + seed * 13) & 255;
  }
  return b;
}

/** FNV-1a (32 bits) over `bytes`, continuing `h`. */
export function fnv(h: number, bytes: Uint8Array): number {
  for (let i = 0; i < bytes.length; i++) h = Math.imul(h ^ bytes[i]!, 0x01000193) >>> 0;
  return h;
};

/** What a reader of `bytes` generated bytes of `seed` should count. */
export function expected(seed: number, bytes: number): Counted {
  let sum = 0x811c9dc5;
  for (let at = 0; at < bytes; at += 65_536) sum = fnv(sum, gen(seed, at, Math.min(65_536, bytes - at)));
  return { count: bytes, sum };
}

/** Why `got` isn't `want` (or undefined when it is). */
export function countedWrong(what: string, got: unknown, want: Counted): string | undefined {
  const g = got as Partial<Counted> & { error?: string } | undefined;
  if (g === undefined || g === null || typeof g !== "object") return `${what}: no count (${JSON.stringify(got)})`;
  if (g.error !== undefined) return `${what}: ${g.error}`;
  if (g.count !== want.count || g.sum !== want.sum) return `${what}: counted ${g.count} bytes with checksum ${g.sum}, not ${want.count} with ${want.sum}`;
  return undefined;
}

const DOWN = 4_000_000;
const UP = 3_000_000;
const POINT = 2_000_000;

export async function streamsClause(d: StreamsClauseDeps): Promise<string> {
  const run = async <T>(name: string, args: unknown = {}, timeoutMs = 120_000): Promise<T> => (await d.request<{ result: T }>("command.run", { name, args }, timeoutMs)).result;
  try {
    for (const id of [A, B]) {
      const folder = join(d.srcDir, id);
      cpSync(join(import.meta.dir, "fixtures", id), folder, { recursive: true });
      await d.install(folder, id);
    }
    // Its page mounted as soon as it ran and registered what it accepts.
    const deadline = Date.now() + 120_000;
    for (;;) {
      const r = await run<{ ready?: boolean }>(`${A}.report`);
      if (r.ready === true) break;
      if (Date.now() > deadline) d.fail(`${A}'s page never said it was ready (it mounts in a frame of its own layer as soon as the plugin runs)`);
      await Bun.sleep(500);
    }
    const wrong: string[] = [];
    type Report = { page: Record<string, unknown>; results: Record<string, unknown> };
    // A command answers at once (a command call has 10 seconds); its work runs on and its result is in `report`.
    const result = async (name: string, bytes: number, pageKey?: string): Promise<Report> => {
      const started = await run<{ started?: string }>(`${A}.${name}`, { bytes });
      if (started.started !== name) d.fail(`${A}.${name} didn't start: ${JSON.stringify(started)}`);
      for (let i = 0; i < 240; i++) {
        const r = await run<Report>(`${A}.report`);
        if (r.results[name] !== undefined && (pageKey === undefined || r.page[pageKey] !== undefined)) return r;
        await Bun.sleep(500);
      }
      return d.fail(`${A}.${name} gave no result in 120 s: ${JSON.stringify(await run(`${A}.report`))}`);
    };
    // Host half to its page.
    const wantDown = expected(1, DOWN);
    const down = await result("down", DOWN, "down");
    for (const w of [countedWrong("the host half's write to its page", down.results.down, wantDown), countedWrong("the page's read of its host half's stream", down.page.down, wantDown)]) if (w !== undefined) wrong.push(w);
    // The page to its host half.
    const wantUp = expected(2, UP);
    const up = await result("up", UP, "upSent");
    for (const w of [countedWrong("the host half's read of its page's stream", up.results.up, wantUp), countedWrong("the page's write to its host half", up.page.upSent, wantUp)]) if (w !== undefined) wrong.push(w);
    // Another plugin's point handler answers with a stream.
    const w5 = countedWrong("the point handler's stream, read by its caller", (await result("point", POINT)).results.point, expected(3, POINT));
    if (w5 !== undefined) wrong.push(w5);
    // A stream connects only a plugin's own halves.
    const nosy = await run<{ opened: string; wrote: string }>(`${B}.nosy`);
    if (!nosy.opened.includes('has no component accepting a stream named "down"')) wrong.push(`${B} opened a stream to a page it hasn't: ${JSON.stringify(nosy.opened)}`);
    if (!nosy.wrote.includes("no stream")) wrong.push(`${B}'s write to a stream that isn't its own: ${JSON.stringify(nosy.wrote)}`);
    // The daemon's log: one line each way per stream, with its bytes.
    const log = d.daemonLog();
    const lines = log.split("\n");
    const has = (a: string, b: string) => lines.some((l) => l.includes(a) && l.includes(b));
    if (!has(`streams: down (`, `opened, ${A} (its host half`)) wrong.push("the daemon's log has no line for the opened stream `down`");
    if (!has(`streams: down (`, `ended by its writer (done): ${DOWN} bytes`)) wrong.push("the daemon's log has no end line for `down` with its bytes");
    if (!has(`streams: up (`, `opened, ${A} (a component) writing to ${A} (its host half`)) wrong.push("the daemon's log has no line for the opened stream `up`");
    if (!has(`streams: up (`, `ended by its writer (done): ${UP} bytes`)) wrong.push("the daemon's log has no end line for `up` with its bytes");
    if (!has(`streams: acceptance-stream-a.sounds/make (`, `opened, ${B} (its host half`)) wrong.push("the daemon's log has no line for the point's stream");
    if (!has(`streams: acceptance-stream-a.sounds/make (`, `ended by its writer (done): ${POINT} bytes`)) wrong.push("the daemon's log has no end line for the point's stream with its bytes");
    if (wrong.length > 0) d.fail(wrong.join("; "));
    return `${STREAMS_CLAUSE}: ${DOWN} bytes host half to page, ${UP} page to host half, ${POINT} from ${B}'s point handler, each checksum equal to the run's (${wantDown.sum}, ${wantUp.sum}, ${expected(3, POINT).sum}); "${nosy.opened.slice(0, 100)}"`;
  } finally {
    for (const id of [B, A]) await d.request("plugin.remove", { id, deleteData: true }).catch(() => undefined);
  }
}
